<?php
namespace App\Services\Accounting;
use App\Models\{Account,JournalEntry};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use RuntimeException;
class AccountingService{
 public function account(int $propertyId,string $code):Account{return Account::where('property_id',$propertyId)->where('code',$code)->firstOrFail();}
 public function post(int $propertyId,string $sourceType,?int $sourceId,string $description,array $lines,?int $userId=null,?string $reference=null,?string $businessDate=null):JournalEntry{return DB::transaction(function()use($propertyId,$sourceType,$sourceId,$description,$lines,$userId,$reference,$businessDate){$debit=round(array_sum(array_map(fn($l)=>(float)($l['debit']??0),$lines)),2);$credit=round(array_sum(array_map(fn($l)=>(float)($l['credit']??0),$lines)),2);if(abs($debit-$credit)>.009||$debit<=0)throw new RuntimeException('Journal entry is not balanced.');if($sourceId){$existing=JournalEntry::where('property_id',$propertyId)->where('source_type',$sourceType)->where('source_id',$sourceId)->where('status','posted')->first();if($existing)return $existing;}$entry=JournalEntry::create(['property_id'=>$propertyId,'reference'=>$reference??'JE-'.now()->format('YmdHis').'-'.Str::upper(Str::random(5)),'entry_date'=>now()->toDateString(),'business_date'=>$businessDate??now()->toDateString(),'source_type'=>$sourceType,'source_id'=>$sourceId,'description'=>$description,'status'=>'posted','created_by'=>$userId]);foreach($lines as $line){$account=$line['account']??$this->account($propertyId,$line['code']);$entry->lines()->create(['account_id'=>$account->id,'description'=>$line['description']??$description,'debit'=>$line['debit']??0,'credit'=>$line['credit']??0]);}return $entry->load('lines.account');});}
 public function postRevenue(int $propertyId,int $sourceId,string $department,float $net,float $tax=0,?int $userId=null):JournalEntry{$gross=$net+$tax;$revenueCode=match($department){'room'=>'4100','restaurant'=>'4200','bar'=>'4300',default=>'4400'};return $this->post($propertyId,'folio_item',$sourceId,'Guest charge: '.$department,[['code'=>'1100','debit'=>$gross],['code'=>$revenueCode,'credit'=>$net],...($tax>0?[['code'=>'2100','credit'=>$tax]]:[])],$userId);}
 public function postPayment(int $propertyId,int $sourceId,string $method,float $amount,?int $userId=null):JournalEntry{$cashCode=match($method){'cash'=>'1000','mtn_momo'=>'1020','airtel_money'=>'1030','bank_transfer','card','card_pos'=>'1010',default=>'1000'};return $this->post($propertyId,'payment',$sourceId,'Customer payment via '.str_replace('_',' ',$method),[['code'=>$cashCode,'debit'=>$amount],['code'=>'1100','credit'=>$amount]],$userId);}
 public function postPosCashSale(int $propertyId,int $paymentId,string $department,string $method,float $amount,?int $userId=null):JournalEntry{$cashCode=match($method){'cash'=>'1000','mtn_momo'=>'1020','airtel_money'=>'1030','bank_transfer','card','card_pos'=>'1010',default=>'1000'};$rev=$department==='bar'?'4300':'4200';return $this->post($propertyId,'pos_payment',$paymentId,'POS cash sale',[['code'=>$cashCode,'debit'=>$amount],['code'=>$rev,'credit'=>$amount]],$userId);}
 public function postSupplierInvoice(int $propertyId,int $invoiceId,float $subtotal,float $tax,?int $userId=null):JournalEntry{return $this->post($propertyId,'supplier_invoice',$invoiceId,'Supplier invoice',[['code'=>'5100','debit'=>$subtotal],...($tax>0?[['code'=>'1300','debit'=>$tax]]:[]),['code'=>'2000','credit'=>$subtotal+$tax]],$userId);}
 public function postSupplierPayment(int $propertyId,int $paymentId,string $method,float $amount,?int $userId=null):JournalEntry{$cashCode=match($method){'cash'=>'1000','mtn_momo'=>'1020','airtel_money'=>'1030','bank_transfer','cheque'=>'1010',default=>'1010'};return $this->post($propertyId,'supplier_payment',$paymentId,'Supplier payment',[['code'=>'2000','debit'=>$amount],['code'=>$cashCode,'credit'=>$amount]],$userId);}
 public function balance(int $propertyId,string $code,?string $to=null):float{$q=\App\Models\JournalLine::query()->join('journal_entries','journal_entries.id','=','journal_lines.journal_entry_id')->join('accounts','accounts.id','=','journal_lines.account_id')->where('journal_entries.property_id',$propertyId)->where('journal_entries.status','posted')->where('accounts.code',$code);if($to)$q->whereDate('journal_entries.entry_date','<=',$to);$row=$q->selectRaw('COALESCE(SUM(journal_lines.debit),0) d,COALESCE(SUM(journal_lines.credit),0) c')->first();return(float)$row->d-(float)$row->c;}
}
